try {
  await $page.setViewport({
    width: 1440,
    height: 1200,
    deviceScaleFactor: 1,
  });

  const response = await $page.goto($json.url, {
    waitUntil: "networkidle2",
    timeout: 60000,
  });

  // Give Amazon extra time to finish rendering
  await new Promise((resolve) => setTimeout(resolve, 3000));

  const finalUrl = $page.url();
  const pageTitle = await $page.title();

  const product = await $page.evaluate(() => {
    const getText = (...selectors) => {
      for (const selector of selectors) {
        const element = document.querySelector(selector);
        const value = element?.innerText?.trim();

        if (value) {
          return value;
        }
      }

      return "";
    };

    const getAttribute = (selectors, attribute) => {
      for (const selector of selectors) {
        const element = document.querySelector(selector);
        const value = element?.getAttribute(attribute);

        if (value) {
          return value;
        }
      }

      return "";
    };

    const getTexts = (...selectors) => {
      for (const selector of selectors) {
        const values = [...document.querySelectorAll(selector)]
          .map((element) => element.innerText?.trim())
          .filter(Boolean);

        if (values.length > 0) {
          return [...new Set(values)];
        }
      }

      return [];
    };

    const cleanBrand = (value) =>
      value.replace(/^Brand:\s*/i, "").trim();

    const asinFromInput =
      document.querySelector("#ASIN")?.getAttribute("value") ||
      document
        .querySelector('input[name="ASIN"]')
        ?.getAttribute("value") ||
      "";

    const asinFromUrl =
      location.pathname.match(
        /\/(?:dp|gp\/product)\/([A-Z0-9]{10})/i
      )?.[1] || "";

    const rawMainImage =
      getAttribute(
        ["#landingImage", "#imgBlkFront", "#main-image"],
        "data-old-hires"
      ) ||
      getAttribute(
        ["#landingImage", "#imgBlkFront", "#main-image"],
        "data-a-dynamic-image"
      ) ||
      getAttribute(
        ["#landingImage", "#imgBlkFront", "#main-image"],
        "src"
      );

    let mainImage = rawMainImage;

    if (rawMainImage?.startsWith("{")) {
      try {
        const imageMap = JSON.parse(rawMainImage);
        mainImage = Object.keys(imageMap)[0] || "";
      } catch {
        mainImage = "";
      }
    }

    const images = [
      ...new Set(
        [
          ...document.querySelectorAll(
            "#altImages img, .imageThumbnail img, #imageBlockThumbs img"
          ),
        ]
          .map(
            (image) =>
              image.getAttribute("data-old-hires") ||
              image.getAttribute("data-src") ||
              image.getAttribute("src") ||
              ""
          )
          .filter(Boolean)
      ),
    ];

    let bulletPoints = getTexts(
      "#feature-bullets li span.a-list-item",
      "#feature-bullets li"
    ).filter((value) => {
      const normalized = value.toLowerCase();

      return (
        value.length > 2 &&
        !normalized.includes("report an issue") &&
        !normalized.includes("see more")
      );
    });

    /*
     * Amazon Merch pages sometimes don't expose the normal
     * #feature-bullets section. Try extracting "About this item".
     */
    if (bulletPoints.length === 0) {
      const bodyText = document.body?.innerText || "";

      const aboutMatch = bodyText.match(
        /About this item\s+([\s\S]*?)(?:See more|Style|Product details|Report an issue)/i
      );

      if (aboutMatch?.[1]) {
        bulletPoints = aboutMatch[1]
          .split(/\n+/)
          .map((value) => value.trim())
          .filter(
            (value) =>
              value.length > 2 &&
              value.length < 500
          );
      }
    }

    const rawBrand = getText(
      "#bylineInfo",
      "a#brand",
      ".po-brand .po-break-word"
    );

    return {
      asin: asinFromInput || asinFromUrl,

      title: getText(
        "#productTitle",
        "#title",
        "h1.a-size-large",
        "h1"
      ),

      brand: cleanBrand(rawBrand),

      price: getText(
        "#corePrice_feature_div .a-offscreen",
        ".apexPriceToPay .a-offscreen",
        ".a-price .a-offscreen",
        "#priceblock_ourprice",
        "#priceblock_dealprice"
      ),

      rating: getText(
        "#acrPopover .a-icon-alt",
        "#averageCustomerReviews .a-icon-alt",
        "#acrPopover"
      ),

      reviewCount: getText(
        "#acrCustomerReviewText",
        "#reviewsMedley .totalReviewCount"
      ),

      bulletPoints,

      description: getText(
        "#productDescription",
        "#aplus_feature_div",
        "#aplus"
      ),

      productSummary: getText(
        "#product-summary",
        "[data-csa-c-content-id='product-summary']"
      ),

      category: getText(
        "#wayfinding-breadcrumbs_feature_div",
        "#nav-subnav"
      ),

      availability: getText(
        "#availability",
        "#outOfStock",
        "#deliveryBlockMessage"
      ),

      mainImage,
      images,
    };
  });

  /*
   * Capture screenshot as a Buffer.
   * Do not use encoding: "base64" here.
   */
  const screenshotBuffer = await $page.screenshot({
    fullPage: true,
    type: "png",
  });

  const screenshotFileName = `${
    product.asin || `amazon-product-${$json.id || Date.now()}`
  }.png`;

  return [
    {
      json: {
        ...$json,
        success: true,
        finalUrl,
        statusCode: response?.status() ?? null,
        pageTitle,
        product,
      },

      binary: {
        screenshot: {
          data: screenshotBuffer.toString("base64"),
          mimeType: "image/png",
          fileName: screenshotFileName,
          fileExtension: "png",
        },
      },
    },
  ];
} catch (error) {
  return [
    {
      json: {
        ...$json,
        success: false,
        error: error.message,
        finalUrl: $page.url(),
      },
    },
  ];
}

