const links = $json.body?.links;

if (!Array.isArray(links)) {
  throw new Error('body.links must be an array');
}

const cleanedLinks = links
  .map(link => String(link).trim())
  .filter(link => link.length > 0);

if (cleanedLinks.length === 0) {
  throw new Error('No valid links were provided');
}

return cleanedLinks.map((url, index) => ({
  json: {
    id: index + 1,
    url
  }
}));

const candidates = $input.all().map(item => ({
  asin: item.json.ASIN,
  status: item.json.Status,
  productIdea: item.json["Product Idea"],
  score: item.json.Score,
  copyrightRisk: item.json["Copyright Risk"],
  trademarkRisk: item.json["Trademark Risk"],
  platformRisk: item.json["Platform Risk"],
  reason: item.json.Reason,
  saferAlternative: item.json["Safer Alternative"],
  title: item.json.Title,
  brand: item.json.Brand,
  category: item.json.Category,
  amazonUrl: item.json["Amazon URL"],
  imageUrl: item.json["Image URL"],
  screenshotPath: item.json.Screenshot
}));

return [{
  json: {
    success: true,
    count: candidates.length,
    candidates
  }
}];
